const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const today = new Date();
const dayIndex = today.getDay();

const configs = {
  0: { audience:'Luxury Travel & Villas', postStyle:'Brand storytelling, no hard sell', ctaStyle:'Explore at skyhousesayulita.com', hookExample:'Above Sayulita. Above the ordinary. SkyHouse.' },
  1: { audience:'Sayulita Rentals (actively searching)', postStyle:'Direct with booking CTA', ctaStyle:'Book at skyhousesayulita.com', hookExample:'Three minutes from the break. Panoramic views of the Pacific. Sleeps 8.' },
  2: { audience:'Riviera Nayarit & Puerto Vallarta Travelers', postStyle:'Aspirational with soft CTA', ctaStyle:'Link in comments for availability', hookExample:'The best address on the Riviera Nayarit is not in a hotel.' },
  3: { audience:'Digital Nomads & Remote Workers', postStyle:'Identity-specific, remote work angle', ctaStyle:'DM for availability', hookExample:'Your next office has an ocean view and the fastest WiFi in Sayulita.' },
  4: { audience:'Sayulita Community & Local Enthusiasts', postStyle:'Experiential, no hard sell, community tone', ctaStyle:'None — pure experience post', hookExample:'This is what Sayulita looks like from above the jungle.' },
  5: { audience:'Mexico Expats & Frequent Travelers', postStyle:'Destination lifestyle with soft CTA', ctaStyle:'Link in comments', hookExample:'The Northside of Sayulita keeps its best address quiet for a reason.' },
  6: { audience:'Surfers & Adventure Travelers', postStyle:'Identity-specific, surf culture', ctaStyle:'DM for availability', hookExample:'Three minutes from the break. Panoramic views of the Pacific. Sleeps 8.' }
};

const config = configs[dayIndex];

return [{
  json: {
    dayIndex,
    dayName: days[dayIndex],
    runDate: today.toISOString().split('T')[0],
    audience: config.audience,
    postStyle: config.postStyle,
    ctaStyle: config.ctaStyle,
    hookExample: config.hookExample
  }
}];

const allFiles = $input.all();
const dayConfig = $('Get Day Config').first().json;

const imageFiles = allFiles.filter(item =>
  item.json.mimeType && (
    item.json.mimeType.includes('image/jpeg') ||
    item.json.mimeType.includes('image/png') ||
    item.json.mimeType.includes('image/webp')
  )
);

if (imageFiles.length === 0) {
  throw new Error('No image files found in the Google Drive folder. Check the folder ID and sharing settings.');
}

const shuffled = [...imageFiles].sort(() => Math.random() - 0.5);
const selected = shuffled.slice(0, Math.min(3, imageFiles.length));

return selected.map((file, index) => ({
  json: {
    photoIndex: index,
    photoFileId: file.json.id,
    photoName: file.json.name,
    photoUrl: `https://drive.google.com/uc?export=download&id=${file.json.id}`,
    dayIndex: dayConfig.dayIndex,
    dayName: dayConfig.dayName,
    runDate: dayConfig.runDate,
    audience: dayConfig.audience,
    postStyle: dayConfig.postStyle,
    ctaStyle: dayConfig.ctaStyle,
    hookExample: dayConfig.hookExample
  }
}));

const uploads = $input.all();
const originalPhotos = $('Pick 3 Random Photos').all();
const dayConfig = $('Get Day Config').first().json;

if (uploads.length === 0) {
  throw new Error('No photos were uploaded to Facebook. Check the Page Access Token and permissions.');
}

const fbPhotoIds = uploads.map(item => item.json.id || item.json.photo_id);
const photoUrls = originalPhotos.map(item => item.json.photoUrl);
const photoNames = originalPhotos.map(item => item.json.photoName);

return [{
  json: {
    fbPhotoIds,
    photoUrls,
    photoNames,
    photoCount: fbPhotoIds.length,
    dayIndex: dayConfig.dayIndex,
    dayName: dayConfig.dayName,
    runDate: dayConfig.runDate,
    audience: dayConfig.audience,
    postStyle: dayConfig.postStyle,
    ctaStyle: dayConfig.ctaStyle,
    hookExample: dayConfig.hookExample
  }
}];

const item = $input.first();
const claudeResponse = item.json;
const prevData = $('Collect Upload Results').first().json;

let postText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content) && claudeResponse.content.length > 0) {
  postText = claudeResponse.content[0].text || '';
}

if (!postText.trim()) {
  throw new Error('Claude returned empty post text. Check API key and request format.');
}

const wordCount = postText.trim().split(/\s+/).length;
const warnings = [];

if (wordCount < 80) warnings.push(`Post may be too short: ${wordCount} words`);
if (wordCount > 260) warnings.push(`Post may be too long: ${wordCount} words`);
if (/\*\*|\*[^*]|\bhashtag\b/i.test(postText)) warnings.push('Possible markdown detected');

return [{
  json: {
    postText: postText.trim(),
    wordCount,
    warnings: warnings.join(' | ') || 'None',
    fbPhotoIds: prevData.fbPhotoIds,
    photoUrls: prevData.photoUrls,
    photoNames: prevData.photoNames,
    dayName: prevData.dayName,
    audience: prevData.audience,
    runDate: prevData.runDate
  }
}];

const item = $input.first();

const fbPostBody = {
  message: item.json.postText,
  attached_media: item.json.fbPhotoIds.map(id => ({ media_fbid: id }))
};

return [{
  json: {
    ...item.json,
    fbPostBodyJson: JSON.stringify(fbPostBody)
  }
}];

const fbPostResponse = $input.first().json;
const prevData = $('Build Facebook Post Body').first().json;

return prevData.photoUrls.map((url, index) => ({
  json: {
    photoUrl: url,
    photoIndex: index,
    postText: prevData.postText,
    fbPostId: fbPostResponse.id || 'unknown',
    fbPhotoIds: prevData.fbPhotoIds,
    dayName: prevData.dayName,
    audience: prevData.audience,
    runDate: prevData.runDate,
    warnings: prevData.warnings
  }
}));

const containers = $input.all();
const prevData = $('Split Photos for Instagram').first().json;

if (containers.length === 0) {
  throw new Error('No Instagram media containers created. Check Instagram credentials and image URLs.');
}

const containerIds = containers.map(item => item.json.id);

return [{
  json: {
    igContainerIds: containerIds,
    postText: prevData.postText,
    fbPostId: prevData.fbPostId,
    dayName: prevData.dayName,
    audience: prevData.audience,
    runDate: prevData.runDate,
    warnings: prevData.warnings,
    photoCount: containerIds.length
  }
}];

const igPublishResponse = $input.first().json;
const prevData = $('Collect Instagram Containers').first().json;

return [{
  json: {
    Date: prevData.runDate,
    Day: prevData.dayName,
    Audience: prevData.audience,
    'Post Preview': prevData.postText.substring(0, 120) + '...',
    'FB Post ID': prevData.fbPostId,
    'IG Post ID': igPublishResponse.id || 'unknown',
    'Photo Count': prevData.photoCount,
    Warnings: prevData.warnings,
    Status: 'Published'
  }
}];
